"use client"
import { Plus, SearchX, FolderOpen } from "lucide-react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"

type Props =
  | { kind: "first-use"; onCreate: () => void }
  | { kind: "no-results"; query: string; onClear: () => void }

// Composed locally: Atlas has no EmptyState component (CAND-030).
export function ProjectsEmpty(props: Props) {
  const first = props.kind === "first-use"
  const Icon = first ? FolderOpen : SearchX
  return (
    <div
      role="status"
      style={{
        display: "grid",
        justifyItems: "center",
        textAlign: "center",
        gap: "var(--atlas-spacing-3)",
        paddingBlock: "var(--atlas-spacing-12)",
        paddingInline: "var(--atlas-spacing-4)",
      }}
    >
      <Icon aria-hidden="true" size={40} color="var(--atlas-foreground-subtle)" />
      <h2 style={{ margin: 0, fontSize: "var(--atlas-text-h3)", fontWeight: "var(--atlas-font-weight-semibold)", color: "var(--atlas-foreground)" }}>
        {first ? "No projects yet" : `No results for “${props.query}”`}
      </h2>
      <p style={{ margin: 0, maxInlineSize: "var(--atlas-content-width-sm)", fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
        {first
          ? "Projects group your files, tasks and teammates in one place. Create one to get started."
          : "Try a different search, or clear it to see every project."}
      </p>
      <div style={{ marginBlockStart: "var(--atlas-spacing-3)" }}>
        {props.kind === "first-use" ? (
          <Button variant="primary" size="md" leadingIcon={<Plus aria-hidden="true" />} onClick={props.onCreate}>
