cat > empty-state/page.tsx <<'EOF'
"use client"
import { useState } from "react"
import { Search } from "lucide-react"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { TabsRoot, TabsList, TabsTrigger } from "@atlas/ui-web/patterns/Tabs/Tabs"
import { ListItem, ListItemContent, ListItemTitle, ListItemDescription } from "@atlas/ui-web/compositions/ListItem/ListItem"
import { FlowShell } from "../_shared/FlowShell"
import { ProjectsEmpty } from "./ProjectsEmpty"
import { NO_RESULTS_QUERY, PROJECTS, SCENARIOS, type Project, type Scenario } from "./schema"

export default function EmptyStatePage() {
  const [scenario, setScenario] = useState<Scenario>("list")
  const [query, setQuery] = useState("")
  const [created, setCreated] = useState<Project[]>([])

  const all = scenario === "first-use" ? created : PROJECTS
  const trimmed = query.trim().toLowerCase()
  const visible = all.filter((p) => p.name.toLowerCase().includes(trimmed))
  const kind = all.length === 0 ? "first-use" : visible.length === 0 ? "no-results" : "list"

  const switchScenario = (value: string) => {
    const next = value as Scenario
    setScenario(next)
    setCreated([])
    setQuery(next === "no-results" ? NO_RESULTS_QUERY : "")
  }
  const clearSearch = () => {
    setQuery("")
    setScenario("list")
  }
  const create = () =>
    setCreated([{ id: "new", name: "Untitled project", updated: "Updated just now" }])

  return (
    <FlowShell title="Projects: empty states" step={0} totalSteps={1} showProgress={false}
      phoneBackground="var(--atlas-background)">
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)", paddingBlockEnd: "var(--atlas-spacing-6)" }}>
        <TabsRoot variant="segmented" size="sm" value={scenario} onValueChange={switchScenario}>
          <TabsList aria-label="Review state">
            {SCENARIOS.map((s) => (
              <TabsTrigger key={s.value} value={s.value}>{s.label}</TabsTrigger>
            ))}
          </TabsList>
        </TabsRoot>

        <h1 style={{ margin: 0, fontSize: "var(--atlas-text-h1)", fontWeight: "var(--atlas-font-weight-bold)", color: "var(--atlas-foreground)" }}>
          Projects
        </h1>

        {kind !== "first-use" && (
          <Input
            type="search"
            size="md"
            aria-label="Search projects"
            placeholder="Search projects"
            leadingIcon={<Search aria-hidden="true" />}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        )}

        {kind === "list" && (
          <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
            {visible.map((p) => (
              <ListItem key={p.id} as="li" variant="outline" size="md">
                <ListItemContent>
                  <ListItemTitle>{p.name}</ListItemTitle>
                  <ListItemDescription>{p.updated}</ListItemDescription>
                </ListItemContent>
              </ListItem>
            ))}
          </ul>
        )}
        {kind === "first-use" && <ProjectsEmpty kind="first-use" onCreate={create} />}
        {kind === "no-results" && <ProjectsEmpty kind="no-results" query={query.trim()} onClear={clearSearch} />}
      </div>
    </FlowShell>
  )
}
